// Order Confirmation Entry
const ctx = $input.item.json;
return [{ json: {
    ...ctx
} }];

// Build context for checkout AI
const ctx = $('Order Confirmation Entry').item.json;

// The parent workflow (01_incoming_message_router) already passed historyText
// inside ctx. We don't need to overwrite it. Just pass ctx along.

return [{ json: {
    ...ctx
} }];

// Parse the AI Agent delivery info response
let raw = '';
if (typeof $input.item.json === 'string') raw = $input.item.json;
else if ($input.item.json && typeof $input.item.json.text === 'string') raw = $input.item.json.text;
else if ($input.item.json && typeof $input.item.json.output === 'string') raw = $input.item.json.output;
else raw = JSON.stringify($input.item.json || {});

const ctx = $('Build Checkout Context').item.json;

let has_delivery = false;
let address = null;
let payment = 'cash_on_delivery';
let customer_name = null;
let customer_mobile = null;
let items = [];
let total_price = 0;

try {
    const jsonStr = raw.match(/```(?:json)?\s*([\s\S]*?)\s*```/) ? raw.match(/```(?:json)?\s*([\s\S]*?)\s*```/)[1] : raw;
    const match = jsonStr.match(/\{[\s\S]*\}/);
    if (match) {
        let result = JSON.parse(match[0]);
        if (result.action_input && typeof result.action_input === 'string') {
            result = JSON.parse(result.action_input.match(/\{[\s\S]*\}/)[0]);
        }
        if (result.has_delivery_info === true || result.has_delivery_info === "true") has_delivery = true;
        if (result.delivery_address) address = result.delivery_address;
        if (result.payment_method) payment = result.payment_method;
        if (result.customer_name) customer_name = result.customer_name;
        if (result.customer_mobile) customer_mobile = result.customer_mobile;
        if (result.items) items = result.items;
        if (result.total_price) {
            let tp = parseFloat(String(result.total_price).replace(/,/g, ''));
            if (!isNaN(tp)) total_price = tp;
        }
    }
} catch(e) {}

// Fallback: Calculate total from items if it's 0 or missing
if (total_price === 0 && Array.isArray(items) && items.length > 0) {
    let calcTotal = 0;
    for (let i of items) {
        if (i.unit_price) {
            let up = parseFloat(String(i.unit_price).replace(/,/g, ''));
            if (!isNaN(up)) {
                calcTotal += up * (i.qty || 1);
            }
        }
    }
    if (calcTotal > 0) total_price = calcTotal;
}

// Ultimate fallback: Scan the raw string itself if it couldn't parse
if (!has_delivery) {
    let lower = raw.toLowerCase();
    if (lower.includes('"has_delivery_info": true') || lower.includes('"has_delivery_info":true') || lower.includes('dilivery') || lower.includes('address') || lower.includes('colombo') || lower.includes('kandy')) {
        has_delivery = true;
        // Try to regex extract the rest to prevent complete data loss
        const addrMatch = lower.match(/"delivery_address":\s*"(.*?)"/);
        if (addrMatch) address = addrMatch[1];
        else address = 'Provided in chat';
        const payMatch = lower.match(/"payment_method":\s*"(.*?)"/);
        if (payMatch) payment = payMatch[1];
        else if (lower.includes('bank') || lower.includes('transfer')) payment = 'bank_transfer';
        else payment = 'cash_on_delivery';

        if (!customer_name) customer_name = 'Customer';
        const mobMatch = raw.match(/07\d{8}/);
        if (mobMatch) customer_mobile = mobMatch[0];
    }
}

return [{ json: {
    ...ctx,
    has_delivery_info: has_delivery,
    delivery_address: address,
    payment_method: payment,
    customer_name: customer_name,
    customer_mobile: customer_mobile,
    items: items,
    total_price: total_price
} }];

// Build the order object with delivery details
const ctx = $('Parse Delivery Info').item.json;
const lastQuote = $input.item.json.message_text ?? '';

let itemsArray = (ctx.items && Array.isArray(ctx.items) && ctx.items.length > 0) 
  ? ctx.items 
  : [{ product_name: 'Order from chat', qty: 1, unit_price: 0 }];

let tp = parseFloat(ctx.total_price) || 0;
// If AI extracted a dollar value like 45 instead of 13500, convert it to LKR
if (tp > 0 && tp < 1000) tp = tp * 300;

// If price is 0, extract it from the bot's last quoted message (e.g. "... is LKR 13,500")
if (tp === 0 && lastQuote) {
    const match = lastQuote.match(/LKR\s*([\d,]+)/i);
    if (match) {
        tp = parseFloat(match[1].replace(/,/g, ''));
    }
}

// Fix item prices and ensure they add up
for (let i of itemsArray) {
    let up = parseFloat(i.unit_price) || 0;
    if (up > 0 && up < 1000) up = up * 300;
    if (up === 0 && tp > 0) up = tp / itemsArray.reduce((sum, item) => sum + (item.qty || 1), 0);
    i.unit_price = up;
}

// Recompute total price to perfectly match items
tp = itemsArray.reduce((sum, item) => sum + ((item.unit_price || 0) * (item.qty || 1)), 0);

return [{ json: {
    ...ctx,
    lastQuote,
    items: JSON.stringify(itemsArray),
    items_array: itemsArray,
    total_price: tp,
    discount_applied: 0.00,
    status: 'confirmed'
} }];
